"use client"

/** Inverted assistant card. Body is bullets, a status, stats, or a checklist. */

import * as React from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import type { StatusTone } from "@/lib/status-tone"
import { ConfidenceBadge } from "@/components/ui/confidence-badge"

export type InsightBullet = { id: string; tone?: StatusTone; text: string }
export type InsightStat = { label: string; value: string; tone?: StatusTone }
export type InsightCheck = { id: string; label: string }

export type InsightCardProps = {
  title: string
  time?: string
  icon?: React.ReactNode
  headline?: string
  body?: React.ReactNode
  variant?: "bullets" | "status" | "stats" | "checklist"
  bullets?: readonly InsightBullet[]
  confidence?: number
  confidenceLabel?: string
  stats?: readonly InsightStat[]
  checks?: readonly InsightCheck[]
  actionLabel?: string
  onAction?: () => void
  className?: string
}

const bulletDot: Record<StatusTone, string> = {
  neutral: "bg-background/50",
  accent: "bg-primary",
  warning: "bg-chart-4",
  critical: "bg-destructive",
  info: "bg-chart-2",
  positive: "bg-primary",
}

export function InsightCard({
  title,
  time,
  icon,
  headline,
  body,
  variant = "status",
  bullets = [],
  confidence,
  confidenceLabel = "Confidence",
  stats = [],
  checks = [],
  actionLabel,
  onAction,
  className,
}: InsightCardProps) {
  return (
    <section
      data-slot="insight-card"
      data-variant={variant}
      className={cn("flex min-w-0 flex-col gap-3 rounded-2xl bg-foreground p-4 text-background", className)}
    >
      <header className="flex items-center gap-2">
        {icon ? (
          <span aria-hidden className="grid size-7 place-items-center rounded-full bg-background/10 text-background [&_svg]:size-3.5">
            {icon}
          </span>
        ) : null}
        <p className="min-w-0 flex-1 truncate text-sm font-medium">{title}</p>
        {time ? <p className="shrink-0 font-mono text-xs text-background/60">{time}</p> : null}
      </header>
      {headline ? <p className="text-base font-medium wrap-break-word">{headline}</p> : null}
      {body ? <div className="text-sm text-background/70 wrap-break-word">{body}</div> : null}
      {variant === "bullets" && bullets.length ? (
        <ul className="flex flex-col gap-2">
          {bullets.map((bullet) => (
            <li key={bullet.id} className="flex items-start gap-2 text-sm">
              <span aria-hidden className={cn("mt-1.5 size-1.5 shrink-0 rounded-full", bulletDot[bullet.tone ?? "accent"])} />
              <span className="min-w-0 wrap-break-word">{bullet.text}</span>
            </li>
          ))}
        </ul>
      ) : null}
      {variant === "status" && confidence != null ? (
        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-between gap-2 text-xs">
            <span className="text-background/70">{confidenceLabel}</span>
            <span className="font-mono text-primary">{Math.round(confidence * 100)}%</span>
          </div>
          <ConfidenceBadge score={confidence} variant="dots" className="text-background" />
        </div>
      ) : null}
      {variant === "stats" && stats.length ? (
        <dl className="flex flex-col">
          {stats.map((stat) => (
            <div key={stat.label} className="flex items-baseline justify-between gap-3 border-t border-background/15 py-2 text-sm first:border-t-0">
              <dt className="text-background/70">{stat.label}</dt>
              <dd className={cn("font-mono", stat.tone === "accent" || stat.tone === "critical" ? "text-primary" : "text-background")}>
                {stat.value}
              </dd>
            </div>
          ))}
        </dl>
      ) : null}
      {variant === "checklist" && checks.length ? (
        <ul className="flex flex-col gap-2">
          {checks.map((check) => (
            <li key={check.id} className="flex items-start gap-2 text-sm">
              <span aria-hidden className="mt-0.5 grid size-4 shrink-0 place-items-center rounded-full bg-primary text-[10px] text-primary-foreground">
                ✓
              </span>
              <span className="min-w-0 wrap-break-word">{check.label}</span>
            </li>
          ))}
        </ul>
      ) : null}
      {actionLabel ? (
        <Button type="button" className="w-full rounded-full" onClick={onAction}>
          {actionLabel}
        </Button>
      ) : null}
    </section>
  )
}

"use client"

// Adapted from LocalMode UI (MIT) — apps/ui/registry/localmode/results/confidence-score-badge/confidence-score-badge.tsx

import { cn } from "@/lib/utils"

export type ConfidenceTier = "high" | "medium" | "low"
export type ConfidenceVariant = "badge" | "dial" | "bar" | "dots" | "segments"

export type ConfidenceBadgeProps = {
  score: number
  thresholds?: { high: number; medium: number }
  variant?: ConfidenceVariant
  /** Dot count for variant="dots". Ignored by the other variants. */
  dots?: number
  className?: string
  classNames?: { root?: string; label?: string }
}

export function confidenceTier(score: number, thresholds = { high: 0.8, medium: 0.5 }): ConfidenceTier {
  if (score >= thresholds.high) return "high"
  if (score >= thresholds.medium) return "medium"
  return "low"
}

export function ConfidenceBadge({
  score,
  thresholds,
  variant = "badge",
  dots = 12,
  className,
  classNames,
}: ConfidenceBadgeProps) {
  const clamped = Math.min(1, Math.max(0, score))
  const percent = Math.round(clamped * 100)
  const tier = confidenceTier(clamped, thresholds)
  const label = `Confidence ${percent}%, ${tier}`
  const tone =
    tier === "high"
      ? "bg-primary text-primary-foreground"
      : tier === "medium"
        ? "bg-secondary text-secondary-foreground"
        : "bg-muted text-muted-foreground"

  if (variant === "dial") {
    const size = 36
    const stroke = 3
    const radius = (size - stroke) / 2
    const circumference = 2 * Math.PI * radius
    return (
      <span
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        className={cn("relative inline-flex size-9 items-center justify-center", className, classNames?.root)}
      >
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90" aria-hidden="true">
          <circle cx={size / 2} cy={size / 2} r={radius} fill="none" strokeWidth={stroke} className="text-muted" stroke="currentColor" />
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            strokeWidth={stroke}
            strokeDasharray={circumference}
            strokeDashoffset={circumference * (1 - clamped)}
            className="text-primary"
            stroke="currentColor"
          />
        </svg>
        <span className={cn("absolute text-[10px] font-medium tabular-nums", classNames?.label)}>{percent}</span>
      </span>
    )
  }

  if (variant === "dots") {
    const count = Math.max(4, Math.min(24, Math.round(dots)))
    const filled = Math.round(clamped * count)
    return (
      <span
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        data-variant="dots"
        className={cn("inline-flex items-center gap-1", className, classNames?.root)}
      >
        {Array.from({ length: count }, (_, index) => (
          <span key={index} aria-hidden className={cn("size-1.5 rounded-full", index < filled ? "bg-primary" : "bg-current opacity-25")} />
        ))}
      </span>
    )
  }

  if (variant === "segments") {
    const count = 5
    const filled = Math.max(0, Math.min(count, Math.round(clamped * count)))
    const lit = clamped >= 0.9 ? "bg-primary" : clamped >= 0.75 ? "bg-chart-4" : "bg-destructive"
    return (
      <span
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        data-variant="segments"
        className={cn("inline-flex items-center gap-1.5", className, classNames?.root)}
      >
        <span aria-hidden className="inline-flex gap-0.5">
          {Array.from({ length: count }, (_, index) => (
            <span key={index} className={cn("h-2 w-2 rounded-[2px]", index < filled ? lit : "bg-muted")} />
          ))}
        </span>
        <span className={cn("font-mono text-xs tabular-nums", classNames?.label)}>{percent}%</span>
      </span>
    )
  }

  if (variant === "bar") {
    return (
      <span className={cn("inline-flex min-w-24 items-center gap-2", className, classNames?.root)} aria-label={label}>
        <span role="meter" aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent} className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted">
          <span className={cn("block h-full rounded-full", tier === "low" ? "bg-muted-foreground" : "bg-primary")} style={{ width: `${percent}%` }} />
        </span>
        <span className={cn("text-xs tabular-nums", classNames?.label)}>{tier}</span>
      </span>
    )
  }

  return (
    <span aria-label={label} className={cn("inline-flex h-5 items-center gap-1 rounded-full px-2 text-xs font-medium", tone, className, classNames?.root)}>
      <span aria-hidden="true">{tier === "high" ? "●" : tier === "medium" ? "◐" : "○"}</span>
      <span className={classNames?.label}>{percent}%</span>
    </span>
  )
}
